using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;

namespace BlueMageSetBuilder;

/// <summary>
/// One place a spell can be learned: which creature, where, and the boss position when
/// it is known. Facts from the FFXIV Online Wiki, generated by tools/make-sources.ps1.
/// </summary>
public sealed record SpellSource(string Creature, string Note, string Place, string Level, string Coords)
{
    /// <summary>"Cave Bat (level 7): Lower La Noscea (X:27, Y:16)".</summary>
    public string Describe()
    {
        var who = this.Creature;
        var extras = new List<string>();
        if (this.Note.Length > 0)
            extras.Add(this.Note.ToLowerInvariant());
        if (this.Level.Length > 0)
            extras.Add($"level {this.Level}");
        if (extras.Count > 0)
            who += $" ({string.Join(", ", extras)})";

        var where = this.Place;
        if (this.Coords.Length > 0)
            where = (where + " " + this.Coords).Trim();

        return where.Length > 0 ? $"{who}: {where}" : who;
    }
}

public static class SpellSources
{
    private const string ResourceName = "BlueMageSetBuilder.Sources.json";

    public const string Credit = "Creature data: FFXIV Online Wiki (ffxiv.consolegameswiki.com)";

    /// <summary>
    /// Spellbook number to its sources. Empty if the file is missing or unreadable:
    /// creature names are a nicety, so their absence must never stop the plugin.
    /// </summary>
    public static Dictionary<uint, List<SpellSource>> Load()
    {
        var result = new Dictionary<uint, List<SpellSource>>();
        try
        {
            using var stream = typeof(SpellSources).Assembly.GetManifestResourceStream(ResourceName);
            if (stream is null)
                return result;

            using var doc = JsonDocument.Parse(stream);
            if (!doc.RootElement.TryGetProperty("Spells", out var spells))
                return result;

            foreach (var spell in spells.EnumerateObject())
            {
                if (!uint.TryParse(spell.Name, out var number))
                    continue;
                if (!spell.Value.TryGetProperty("Sources", out var sources))
                    continue;

                // PowerShell writes a one-item list as a bare object, so accept both.
                var items = sources.ValueKind == JsonValueKind.Array
                    ? sources.EnumerateArray().ToList()
                    : new List<JsonElement> { sources };

                result[number] = items
                    .Where(e => e.ValueKind == JsonValueKind.Object)
                    .Select(e => new SpellSource(Str(e, "Creature"), Str(e, "Note"), Str(e, "Place"), Str(e, "Level"), Str(e, "Coords")))
                    .Where(s => s.Creature.Length > 0)
                    .ToList();
            }
        }
        catch (Exception ex)
        {
            Service.Log.Warning(ex, "Could not read Sources.json; creature names will be missing");
        }

        return result;
    }

    /// <summary>
    /// The source that matches where the game itself says to learn the spell, so the
    /// table can name the creature at that place rather than an arbitrary one.
    /// </summary>
    public static SpellSource? MatchGameSource(IReadOnlyList<SpellSource> sources, string gameSource)
    {
        if (gameSource.Length == 0 || sources.Count == 0)
            return null;

        // Compared with punctuation and case stripped: the game writes "Tam–Tara" with
        // an en dash and wraps "Whorleater" in emphasis markers, the wiki does neither.
        // Containment either way lets "The Bowl of Embers (Extreme)" match the wiki's
        // "The Bowl of Embers".
        var game = Normalize(gameSource);
        var gameBase = Normalize(StripBrackets(gameSource));
        return sources.FirstOrDefault(s =>
               {
                   var place = Normalize(s.Place);
                   return place.Length > 0 && (place.Contains(game) || game.Contains(place));
               })
               // Fallback: ignore the difficulty in brackets and compare each place the
               // wiki lists on its own. The game names primal trials "(Extreme)" where
               // the wiki says "(Hard)", and some entries list two places together.
               ?? sources.FirstOrDefault(s => s.Place
                   .Split(new[] { ',', '/', ';' }, StringSplitOptions.RemoveEmptyEntries)
                   .Select(part => Normalize(StripBrackets(part)))
                   .Any(part => part.Length > 0 && part == gameBase))
               // Totem rewards: the game says "Whalaqee Totem", the wiki names the
               // requirement in Place, such as "Learn 10 Blue Magic Spells".
               ?? sources.FirstOrDefault(s => gameSource.StartsWith("Whalaqee", StringComparison.OrdinalIgnoreCase) &&
                                              s.Creature.Contains("Totem", StringComparison.OrdinalIgnoreCase));
    }

    private static string StripBrackets(string s) =>
        System.Text.RegularExpressions.Regex.Replace(s, @"\([^)]*\)", string.Empty);

    private static string Normalize(string s) =>
        new(s.Where(char.IsLetterOrDigit).Select(char.ToLowerInvariant).ToArray());

    private static string Str(JsonElement e, string name) =>
        e.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString()?.Trim() ?? string.Empty : string.Empty;
}
